interface Renderer {
  render(data: any, container: HTMLElement): void
}
class SvgRenderer implements Renderer {
  render(data: any, container: HTMLElement) { /* draw SVG */ }
}
class Registry {
  private map = new Map<string, (ctx?: any) => Renderer>()
  register(name: string, factory: (ctx?: any) => Renderer) { this.map.set(name, factory) }
  create(name: string, ctx?: any) { return this.map.get(name)!(ctx) }
