## Code Example

```typescript
interface Context { req: any; res: any; payload?: any }
interface Policy {
  name: string
  run(ctx: Context, next: () => Promise<void>): Promise<void>
}
class Registry {
  private store = new Map<string, () => Policy>()
  register(name: string, factory: () => Policy){ this.store.set(name, factory) }
  resolve(name: string): Policy | null { const f = this.store.get(name); return f ? f() : null }
}
class PolicyChain {
  constructor(private policies: Policy[]){}
  async execute(ctx: Context){
    for (const p of this.policies){ await p.run(ctx, async ()=>{}) }
  }
}
// Usage
const registry = new Registry()
registry.register('JwtAuth', ()=> new JwtAuthPolicy())
registry.register('RBAC', ()=> new RoleBasedPolicy())
registry.register('Quota', ()=> new QuotaPolicy())
registry.register('Transform', ()=> new JsonTransformPolicy())
const chain = new PolicyChain([
  registry.resolve('JwtAuth')!,
  registry.resolve('RBAC')!,
  registry.resolve('Quota')!,
  registry.resolve('Transform')!
])
```

